using Clock=chrono::steady_clock;
static long long nowms(){return chrono::duration_cast<chrono::milliseconds>(Clock::now().time_since_epoch()).count();}
struct Config {string listen,root,origin,name,ca,cert,key; int maxconn,headers,ht,idle,wt,maxreq,depth; int rootfd=-1; SSL_CTX *ctx=nullptr; sockaddr_storage originaddr{},listenaddr{}; socklen_t originlen=0,listenlen=0; ~Config(){if(rootfd>=0)close(rootfd);if(ctx)SSL_CTX_free(ctx);} };
static shared_ptr<Config> current; static string configpath; static volatile sig_atomic_t reload_flag=0; static atomic<int> connections{0};
static void sigh(int){reload_flag=1;}
static bool address(const string&s,sockaddr_storage &out,socklen_t &len){auto p=s.rfind(':');if(p==string::npos||p==0||p+1==s.size())return false;string host=s.substr(0,p),port=s.substr(p+1);if(host.size()>2&&host.front()=='['&&host.back()==']')host=host.substr(1,host.size()-2);for(char c:port)if(c<'0'||c>'9')return false; long v=strtol(port.c_str(),nullptr,10);if(v<1||v>65535)return false;addrinfo h{},*r=nullptr;h.ai_family=AF_UNSPEC;h.ai_socktype=SOCK_STREAM;h.ai_flags=AI_NUMERICHOST|AI_NUMERICSERV;if(getaddrinfo(host.c_str(),port.c_str(),&h,&r))return false;memcpy(&out,r->ai_addr,r->ai_addrlen);len=r->ai_addrlen;freeaddrinfo(r);return true;}
static string trim(string s){size_t a=s.find_first_not_of(" \t\r\n"),b=s.find_last_not_of(" \t\r\n");return a==string::npos?string():s.substr(a,b-a+1);}
static bool number(const string&s,int&v){if(s.empty())return false;long long n=0;for(char c:s){if(c<'0'||c>'9')return false;n=n*10+(c-'0');if(n>INT_MAX)return false;}if(n<1)return false;v=(int)n;return true;}
static shared_ptr<Config> load(){FILE*f=fopen(configpath.c_str(),"r");if(!f)return {};map<string,string> m;char *line=nullptr;size_t cap=0;ssize_t n;bool ok=true;while((n=getline(&line,&cap,f))>=0){string s(line,n);s=trim(s);if(s.empty()||s[0]=='#')continue;auto p=s.find('=');if(p==string::npos){ok=false;break;}string k=trim(s.substr(0,p)),v=trim(s.substr(p+1));if(k.empty()||v.empty()||m.count(k)){ok=false;break;}m[k]=v;}free(line);if(ferror(f))ok=false;fclose(f);const vector<string> keys={"listen","root","max_connections","header_bytes","header_timeout_ms","idle_timeout_ms","write_timeout_ms","max_requests","pipeline_depth","origin_address","tls_name","tls_ca","tls_cert","tls_key"};if(!ok||m.size()!=keys.size())return {};for(auto&k:keys)if(!m.count(k))return {};auto c=make_shared<Config>();c->listen=m["listen"];c->root=m["root"];c->origin=m["origin_address"];c->name=m["tls_name"];c->ca=m["tls_ca"];c->cert=m["tls_cert"];c->key=m["tls_key"];if(c->root[0]!='/'||c->ca[0]!='/'||c->cert[0]!='/'||c->key[0]!='/'||c->name.empty())return {};if(!number(m["max_connections"],c->maxconn)||!number(m["header_bytes"],c->headers)||!number(m["header_timeout_ms"],c->ht)||!number(m["idle_timeout_ms"],c->idle)||!number(m["write_timeout_ms"],c->wt)||!number(m["max_requests"],c->maxreq)||!number(m["pipeline_depth"],c->depth)||!address(c->listen,c->listenaddr,c->listenlen)||!address(c->origin,c->originaddr,c->originlen))return {};c->rootfd=open(c->root.c_str(),O_RDONLY|O_DIRECTORY|O_CLOEXEC);if(c->rootfd<0)return {};c->ctx=SSL_CTX_new(TLS_client_method());if(!c->ctx)return {};SSL_CTX_set_min_proto_version(c->ctx,TLS1_2_VERSION);SSL_CTX_set_max_proto_version(c->ctx,TLS1_3_VERSION);SSL_CTX_set_verify(c->ctx,SSL_VERIFY_PEER,nullptr);if(SSL_CTX_load_verify_locations(c->ctx,c->ca.c_str(),nullptr)!=1||SSL_CTX_use_certificate_chain_file(c->ctx,c->cert.c_str())!=1||SSL_CTX_use_PrivateKey_file(c->ctx,c->key.c_str(),SSL_FILETYPE_PEM)!=1||SSL_CTX_check_private_key(c->ctx)!=1)return {};return c;}
static bool waitfd(int fd,short events,long long until){while(true){long long t=until-nowms();if(t<=0)return false;pollfd p{fd,events,0};int r=poll(&p,1,(int)min<long long>(t,INT_MAX));if(r>0)return (p.revents&(events|POLLERR|POLLHUP|POLLNVAL))!=0;if(r==0)return false;if(errno!=EINTR)return false;}}
static bool sendall(int fd,const char*p,size_t n,int timeout){long long end=nowms()+timeout;while(n){ssize_t x=send(fd,p,n,MSG_NOSIGNAL);if(x>0){p+=x;n-=x;end=nowms()+timeout;}else if(x<0&&(errno==EAGAIN||errno==EWOULDBLOCK)){if(!waitfd(fd,POLLOUT,end))return false;}else if(x<0&&errno==EINTR)continue;else return false;}return true;}
static string lower(string s){for(char &c:s)if(c>='A'&&c<='Z')c+=32;return s;}
static bool tokenchar(unsigned char c){return (c>='0'&&c<='9')||(c>='a'&&c<='z')||(c>='A'&&c<='Z')||strchr("!#$%&'*+-.^_`|~",c);}
static bool validutf(const string&s){for(size_t i=0;i<s.size();){unsigned char c=s[i++];if(c<0x80)continue;int n;unsigned int cp;if(c>=0xc2&&c<=0xdf){n=1;cp=c&31;}else if(c>=0xe0&&c<=0xef){n=2;cp=c&15;}else if(c>=0xf0&&c<=0xf4){n=3;cp=c&7;}else return false;if(i+n>s.size())return false;for(int j=0;j<n;j++){unsigned char d=s[i++];if((d&0xc0)!=0x80)return false;cp=(cp<<6)|(d&63);}if((n==2&&cp<0x800)||(n==3&&cp<0x10000)||(cp>=0xd800&&cp<=0xdfff)||cp>0x10ffff)return false;}return true;}
static int hex(char c){if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;if(c>='A'&&c<='F')return c-'A'+10;return -1;}
static bool decodepath(const string&t,string&path){if(t.empty()||t[0]!='/'||t.find('#')!=string::npos)return false;size_t q=t.find('?');string x=t.substr(0,q);for(size_t i=0;i<x.size();i++){unsigned char c=x[i];if(c=='%'){if(i+2>=x.size()||hex(x[i+1])<0||hex(x[i+2])<0)return false;c=(hex(x[i+1])<<4)|hex(x[i+2]);i+=2;}if(!c||c=='\\'||c<32||c==127)return false;path.push_back(c);}return validutf(path);}
struct Req{string method,target,version,path,host;vector<pair<string,string>> hdr;bool close=false;int hosts=0,cl=0,te=0;string length;};
static bool hastoken(const string&s,const string&key){size_t pos=0;while(pos<=s.size()){size_t e=s.find(',',pos);string t=lower(trim(s.substr(pos,e==string::npos?string::npos:e-pos)));if(t==key)return true;if(e==string::npos)break;pos=e+1;}return false;}
static bool parse(const string&s,Req&r){size_t p=s.find("\r\n");if(p==string::npos)return false;string l=s.substr(0,p);size_t a=l.find(' '),b=a==string::npos?string::npos:l.find(' ',a+1);if(a==string::npos||b==string::npos||a==0||b==a+1||b+1>=l.size()||l.find(' ',b+1)!=string::npos)return false;r.method=l.substr(0,a);r.target=l.substr(a+1,b-a-1);r.version=l.substr(b+1);for(unsigned char c:r.method)if(!tokenchar(c))return false;for(unsigned char c:r.target)if(c<=32||c==127)return false;if(r.version!="HTTP/1.1"&&r.version!="HTTP/1.0")return false;if(!decodepath(r.target,r.path))return false;r.close=r.version=="HTTP/1.0";size_t at=p+2;while(at<s.size()){size_t e=s.find("\r\n",at);if(e==string::npos)return false;if(e==at)break;string h=s.substr(at,e-at);auto colon=h.find(':');if(colon==string::npos||colon==0)return false;for(size_t i=0;i<colon;i++)if(!tokenchar((unsigned char)h[i]))return false;string k=lower(h.substr(0,colon)),v=trim(h.substr(colon+1));for(unsigned char c:v)if(c==0||c=='\r'||c=='\n')return false;r.hdr.emplace_back(k,v);if(k=="host"){r.hosts++;r.host=v;}if(k=="content-length"){r.cl++;r.length=v;}if(k=="transfer-encoding")r.te++;if(k=="connection"&&hastoken(v,"close"))r.close=true;at=e+2;}return true;}
static const char* reason(int s){switch(s){case 200:return "OK";case 400:return "Bad Request";case 403:return "Forbidden";case 404:return "Not Found";case 405:return "Method Not Allowed";case 431:return "Request Header Fields Too Large";case 502:return "Bad Gateway";default:return "Response";}}
static bool response(int fd,int status,unsigned long long len,bool clos,int timeout,const string&extra=""){string h="HTTP/1.1 "+to_string(status)+" "+reason(status)+"\r\nContent-Length: "+to_string(len)+"\r\nConnection: "+(clos?"close":"keep-alive")+"\r\n"+extra+"\r\n";return sendall(fd,h.data(),h.size(),timeout);}
static int fileopen(const Config&c,const string&path,int &fd,off_t &size){vector<string> parts;size_t at=1;while(at<=path.size()){size_t e=path.find('/',at);string x=path.substr(at,e==string::npos?string::npos:e-at);if(x=="..")return 403;if(!x.empty()&&x!=".")parts.push_back(x);if(e==string::npos)break;at=e+1;}if(parts.empty())return 403;int dir=dup(c.rootfd);if(dir<0)return 404;for(size_t i=0;i<parts.size();i++){bool last=i+1==parts.size();int f=openat(dir,parts[i].c_str(),O_RDONLY|O_NOFOLLOW|O_NONBLOCK|O_CLOEXEC|(last?0:O_DIRECTORY));if(f<0){int err=errno;struct stat st{};bool symlink=fstatat(dir,parts[i].c_str(),&st,AT_SYMLINK_NOFOLLOW)==0&&S_ISLNK(st.st_mode);close(dir);return symlink||err==ELOOP||err==EACCES?403:404;}close(dir);dir=f;}struct stat st{};if(fstat(dir,&st)||!S_ISREG(st.st_mode)||(!path.empty()&&path.back()=='/')){close(dir);return 403;}fd=dir;size=st.st_size;return 200;}
struct TLS {int fd=-1;SSL*ssl=nullptr;~TLS(){if(ssl)SSL_free(ssl);if(fd>=0)close(fd);}};
static bool sslwait(TLS&t,int rc,long long deadline){int e=SSL_get_error(t.ssl,rc);if(e==SSL_ERROR_WANT_READ)return waitfd(t.fd,POLLIN,deadline);if(e==SSL_ERROR_WANT_WRITE)return waitfd(t.fd,POLLOUT,deadline);return false;}
static bool tlsconnect(TLS&t,const Config&c){t.fd=socket(c.originaddr.ss_family,SOCK_STREAM|SOCK_NONBLOCK|SOCK_CLOEXEC,0);if(t.fd<0)return false;long long deadline=nowms()+c.wt;int r=connect(t.fd,(sockaddr*)&c.originaddr,c.originlen);if(r<0&&errno!=EINPROGRESS)return false;if(r<0){if(!waitfd(t.fd,POLLOUT,deadline))return false;int err=0;socklen_t n=sizeof(err);if(getsockopt(t.fd,SOL_SOCKET,SO_ERROR,&err,&n)||err)return false;}t.ssl=SSL_new(c.ctx);if(!t.ssl)return false;SSL_set_fd(t.ssl,t.fd);if(SSL_set_tlsext_host_name(t.ssl,c.name.c_str())!=1||SSL_set1_host(t.ssl,c.name.c_str())!=1)return false;while((r=SSL_connect(t.ssl))!=1)if(!sslwait(t,r,deadline))return false;return SSL_get_verify_result(t.ssl)==X509_V_OK;}
static bool tlswrite(TLS&t,const char*p,size_t n,int timeout){long long deadline=nowms()+timeout;while(n){int r=SSL_write(t.ssl,p,(int)min<size_t>(n,INT_MAX));if(r>0){p+=r;n-=r;deadline=nowms()+timeout;}else if(!sslwait(t,r,deadline))return false;}return true;}
static int tlsread(TLS&t,char*p,int n,int timeout){long long deadline=nowms()+timeout;while(true){int r=SSL_read(t.ssl,p,n);if(r>0)return r;if(!sslwait(t,r,deadline))return -1;}}
static bool decimal(const string&s,unsigned long long &v){if(s.empty())return false;v=0;for(char c:s){if(c<'0'||c>'9'||v>(ULLONG_MAX-(c-'0'))/10)return false;v=v*10+(c-'0');}return true;}
static bool proxy(int client,const Config&c,const Req&r,bool clos){TLS t;if(!tlsconnect(t,c))return response(client,502,0,clos,c.wt);string target=r.target.substr(8);if(target.empty()||target[0]!='/')target="/"+target;string out=r.method+" "+target+" HTTP/1.1\r\nHost: "+r.host+"\r\nConnection: close\r\n\r\n";if(!tlswrite(t,out.data(),out.size(),c.wt))return response(client,502,0,clos,c.wt);string buf;size_t end=string::npos;char tmp[16384];while((end=buf.find("\r\n\r\n"))==string::npos){if(buf.size()>65536)return response(client,502,0,clos,c.wt);int n=tlsread(t,tmp,sizeof(tmp),c.wt);if(n<=0)return response(client,502,0,clos,c.wt);buf.append(tmp,n);}size_t first=buf.find("\r\n");string line=buf.substr(0,first);if(line.size()<12||(line.compare(0,9,"HTTP/1.1 ")&&line.compare(0,9,"HTTP/1.0 "))||!isdigit((unsigned char)line[9])||!isdigit((unsigned char)line[10])||!isdigit((unsigned char)line[11]))return response(client,502,0,clos,c.wt);int status=(line[9]-'0')*100+(line[10]-'0')*10+line[11]-'0';unsigned long long len=0;bool got=false;string extra;size_t p=first+2;while(p<end){size_t e=buf.find("\r\n",p);if(e==string::npos||e>end)return response(client,502,0,clos,c.wt);string h=buf.substr(p,e-p);size_t colon=h.find(':');if(colon==string::npos||colon==0)return response(client,502,0,clos,c.wt);for(size_t i=0;i<colon;i++)if(!tokenchar(h[i]))return response(client,502,0,clos,c.wt);string k=lower(h.substr(0,colon)),v=trim(h.substr(colon+1));if(k=="content-length"){if(got||!decimal(v,len))return response(client,502,0,clos,c.wt);got=true;}else if(k=="transfer-encoding")return response(client,502,0,clos,c.wt);else if(k!="connection"&&k!="keep-alive"&&k!="proxy-connection"&&k!="upgrade"&&k!="trailer")extra+=h+"\r\n";p=e+2;}if(!got)return response(client,502,0,clos,c.wt);if(!response(client,status,len,clos,c.wt,extra))return false;if(r.method=="HEAD"||status==204||status==304)return true;size_t start=end+4;unsigned long long left=len;size_t initial=(size_t)min<unsigned long long>(left,buf.size()-start);if(initial&&!sendall(client,buf.data()+start,initial,c.wt))return false;left-=initial;while(left){int n=tlsread(t,tmp,(int)min<unsigned long long>(left,sizeof(tmp)),c.wt);if(n<=0)return false;if(!sendall(client,tmp,n,c.wt))return false;left-=n;}return true;}
static void handle(int fd,shared_ptr<Config> c){string buf;int count=0;while(count<c->maxreq){long long idle=nowms()+c->idle,deadline=0;size_t end=string::npos;int failure=0;while(true){end=buf.find("\r\n\r\n");if(end!=string::npos){if(end+4>(size_t)c->headers)failure=431;break;}for(size_t i=0;i<buf.size();i++){if(buf[i]=='\0'||(buf[i]=='\n'&&(i==0||buf[i-1]!='\r'))||(buf[i]=='\r'&&i+1<buf.size()&&buf[i+1]!='\n')){failure=400;break;}}if(failure)break;if(buf.size()>=(size_t)c->headers){failure=431;break;}if(!buf.empty()&&!deadline)deadline=nowms()+c->ht;long long limit=deadline?deadline:idle;if(!waitfd(fd,POLLIN,limit)){if(deadline)failure=400;else return;break;}char tmp[8192];size_t nmax=min<size_t>(sizeof(tmp),(size_t)c->headers-buf.size());ssize_t n=recv(fd,tmp,nmax,0);if(n>0){if(buf.empty())deadline=nowms()+c->ht;buf.append(tmp,n);}else if(n==0)return;else if(errno==EINTR||errno==EAGAIN||errno==EWOULDBLOCK)continue;else return;}if(failure){response(fd,failure,0,true,c->wt);return;}string head=buf.substr(0,end+4);buf.erase(0,end+4);Req r;if(!parse(head,r)){response(fd,400,0,true,c->wt);return;}count++;bool clos=r.close||count>=c->maxreq;bool gateway=r.target.compare(0,9,"/gateway/")==0;unsigned long long length=0;if(r.te||r.cl>1||(r.cl&&(!decimal(r.length,length)||length!=0))){response(fd,400,0,true,c->wt);return;}if(gateway&&(r.hosts!=1||r.host.empty())){response(fd,400,0,true,c->wt);return;}if(r.method!="GET"&&r.method!="HEAD"){if(!response(fd,405,0,clos,c->wt))return;if(clos)return;continue;}if(gateway){if(!proxy(fd,*c,r,clos))return;}else{int file=-1;off_t size=0;int status=fileopen(*c,r.path,file,size);if(status!=200){if(!response(fd,status,0,clos,c->wt))return;}else{bool ok=response(fd,200,size,clos,c->wt,"Content-Type: application/octet-stream\r\n");if(ok&&r.method=="GET"){char b[32768];off_t left=size;while(left>0){ssize_t n=read(file,b,(size_t)min<off_t>(left,sizeof(b)));if(n>0){if(!sendall(fd,b,n,c->wt)){ok=false;break;}left-=n;}else if(n<0&&errno==EINTR)continue;else{ok=false;break;}}}close(file);if(!ok)return;}}if(clos)return;}}
struct Client{int fd;shared_ptr<Config> cfg;};static void*worker(void*x){unique_ptr<Client> c((Client*)x);handle(c->fd,c->cfg);close(c->fd);connections--;return nullptr;}
int main(int argc,char**argv){signal(SIGPIPE,SIG_IGN);signal(SIGHUP,sigh);if(argc!=3||string(argv[1])!="--config")return 1;configpath=argv[2];auto c=load();if(!c)return 1;atomic_store(&current,c);int listener=socket(c->listenaddr.ss_family,SOCK_STREAM|SOCK_NONBLOCK|SOCK_CLOEXEC,0);if(listener<0)return 1;int one=1;setsockopt(listener,SOL_SOCKET,SO_REUSEADDR,&one,sizeof(one));if(bind(listener,(sockaddr*)&c->listenaddr,c->listenlen)||listen(listener,4096))return 1;pthread_attr_t attr;pthread_attr_init(&attr);pthread_attr_setdetachstate(&attr,PTHREAD_CREATE_DETACHED);pthread_attr_setstacksize(&attr,131072);while(true){if(reload_flag){reload_flag=0;auto next=load();if(next&&next->listen==c->listen){c=next;atomic_store(&current,c);}}pollfd p{listener,POLLIN,0};int n=poll(&p,1,200);if(n<0){if(errno==EINTR)continue;break;}if(n==0)continue;while(true){int fd=accept4(listener,nullptr,nullptr,SOCK_NONBLOCK|SOCK_CLOEXEC);if(fd<0){if(errno==EINTR)continue;break;}auto cfg=atomic_load(&current);if(connections.fetch_add(1)>=cfg->maxconn){connections--;close(fd);continue;}auto client=new Client{fd,cfg};pthread_t tid;if(pthread_create(&tid,&attr,worker,client)){delete client;connections--;close(fd);}}}close(listener);return 0;}
